parts.openscad_module:
$fn = 128;

chain_pitch = 12.7;
roller_d    = 7.92;
num_teeth   = 17;
thickness   = 8;
bore_d      = 10;
hub_od      = 22;
hub_h       = 14;
bore_clear  = 0.1;
tooth_clear = 0.3;

pitch_d = chain_pitch / sin(180 / num_teeth);
outer_d = pitch_d + roller_d * 0.8;
root_d  = pitch_d - roller_d * 1.1;

module ansi40_sprocket() {
  difference() {
    union() {
      cylinder(h = thickness, d = outer_d, center = true);
      cylinder(h = hub_h, d = hub_od, center = true);
    }
    for (i = [0 : num_teeth - 1])
      rotate([0, 0, 360 * i / num_teeth])
        translate([pitch_d/2, 0, 0])
          cylinder(h = thickness + 2, d = roller_d + tooth_clear, center = true, $fn = 32);
    cylinder(h = thickness + 2, d = root_d, center = true);
    cylinder(h = hub_h + 2, d = bore_d + bore_clear, center = true, $fn = 64);
    translate([bore_d/2 + 5, 0, 0])
      rotate([90, 0, 0])
        cylinder(h = hub_od + 2, d = 4.5, center = true, $fn = 32);
  }
}

ansi40_sprocket();
